from pathlib import Path

root = Path("VK2SpotifyAndroid")
p = root / "app/src/main/java/com/vk2spotify/transfer/MainActivity.java"
s = p.read_text(encoding="utf-8")

old_set = '        setContentView(shell);\n        updateTrackCount();'
new_set = '        setContentView(shell);\n        shell.setOnApplyWindowInsetsListener((v, insets) -> {\n            int topInset = insets.getSystemWindowInsetTop();\n            int bottomInset = insets.getSystemWindowInsetBottom();\n            root.setPadding(dp(18), dp(18) + topInset, dp(18), dp(36) + bottomInset);\n            return insets;\n        });\n        shell.requestApplyInsets();\n        updateTrackCount();'
if old_set in s:
    s = s.replace(old_set, new_set, 1)

old_overlay = '        overlay.addView(column, new FrameLayout.LayoutParams(\n                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));\n        return overlay;'
new_overlay = '        overlay.addView(column, new FrameLayout.LayoutParams(\n                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));\n        overlay.setOnApplyWindowInsetsListener((v, insets) -> {\n            overlay.setPadding(0, insets.getSystemWindowInsetTop(), 0, insets.getSystemWindowInsetBottom());\n            return insets;\n        });\n        return overlay;'
if old_overlay in s:
    s = s.replace(old_overlay, new_overlay, 1)

start = s.index("    private void startVkCollection() {")
end = s.index("    private void startSpotifyLogin() {")
new_methods = '    private void startVkCollection() {\n        String url = vkWebView.getUrl();\n        if (url == null || !(url.contains("vk.com") || url.contains("vk.ru"))) {\n            toast("Сначала открой VK Музыку");\n            return;\n        }\n        vkStatusText.setText("Готовлю страницу VK…");\n        String resetJs = "(function(){" +\n                "window.__vk2s={tracks:{},round:0,candidates:0};" +\n                "const all=[document.scrollingElement,document.documentElement,document.body,...document.querySelectorAll(\'*\')];" +\n                "for(const e of all){try{if(e&&e.scrollHeight>e.clientHeight+120)e.scrollTop=0;}catch(x){}}" +\n                "window.scrollTo(0,0);return true;})()";\n        vkWebView.evaluateJavascript(resetJs, value ->\n                handler.postDelayed(() -> autoScrollVk(0, -1, 0), 650));\n    }\n\n    private void autoScrollVk(int step, long lastCount, int stableCount) {\n        if (step > 120 || stableCount >= 14) {\n            extractVkTracks();\n            return;\n        }\n\n        vkWebView.evaluateJavascript(vkSnapshotScript(true), value -> {\n            try {\n                Object decoded = new JSONTokener(value).nextValue();\n                String json = decoded instanceof String ? (String) decoded : "{}";\n                JSONObject info = new JSONObject(json);\n                long count = info.optLong("count", 0);\n                int candidates = info.optInt("candidates", 0);\n                boolean moved = info.optBoolean("moved", false);\n                int nextStable = count == lastCount ? stableCount + 1 : 0;\n\n                if (step % 2 == 0) {\n                    String state = "Нашёл " + count + " трек" + pluralTracks((int) count);\n                    if (candidates > 0) state += " • кандидатов: " + candidates;\n                    if (moved) state += " • листаю…";\n                    vkStatusText.setText(state);\n                }\n                handler.postDelayed(() -> autoScrollVk(step + 1, count, nextStable), 420);\n            } catch (Exception e) {\n                handler.postDelayed(() -> autoScrollVk(step + 1, lastCount, stableCount + 1), 500);\n            }\n        });\n    }\n\n    private String vkSnapshotScript(boolean doScroll) {\n        return "(function(){" +\n                "if(!window.__vk2s)window.__vk2s={tracks:{},round:0,candidates:0};" +\n                "const S=window.__vk2s;S.round++;" +\n                "const clean=s=>(s||\'\').replace(/\\\\s+/g,\' \').replace(/^[\\\\s·•|—–-]+|[\\\\s·•|—–-]+$/g,\'\').trim();" +\n                "const bad=s=>{let x=clean(s).toLowerCase();return !x||x.length>220||/^(\\\\d{1,2}:)?\\\\d{1,2}:\\\\d{2}$/.test(x)||/^(play|pause|more|ещ[её]|воспроизвести|пауза|добавить|скачать|поделиться|текст песни|lyrics|очередь|shuffle|repeat)$/.test(x);};" +\n                "const add=(artist,title,src)=>{artist=clean(artist);title=clean(title);if(bad(artist)||bad(title)||artist===title)return;" +\n                "if(title.length<1||artist.length<1||title.length>220||artist.length>180)return;" +\n                "let k=(artist+\'|\'+title).toLowerCase().replace(/[^a-zа-яё0-9|]+/gi,\'\');if(k.length<4)return;" +\n                "if(!S.tracks[k])S.tracks[k]={artist:artist,title:title,source:src||\'\'};};" +\n                "const txt=e=>clean(e&&(e.innerText||e.textContent||\'\'));" +\n                "const rows=new Set();" +\n                "const sels=[\'.audio_row\',\'[class*=\\\\\\\"audio_row\\\\\\\"]\',\'[class*=\\\\\\\"AudioRow\\\\\\\"]\',\'[class*=\\\\\\\"audio-item\\\\\\\"]\',\'[class*=\\\\\\\"AudioItem\\\\\\\"]\',\'[class*=\\\\\\\"track-item\\\\\\\"]\',\'[class*=\\\\\\\"TrackItem\\\\\\\"]\',\'[data-testid*=\\\\\\\"audio\\\\\\\"]\',\'[data-testid*=\\\\\\\"track\\\\\\\"]\',\'[data-test-id*=\\\\\\\"audio\\\\\\\"]\',\'[data-test-id*=\\\\\\\"track\\\\\\\"]\'];" +\n                "for(const q of sels){try{for(const e of document.querySelectorAll(q))rows.add(e);}catch(x){}}" +\n                "for(const e of document.querySelectorAll(\'[aria-label],[title]\')){let a=clean(e.getAttribute(\'aria-label\')||e.getAttribute(\'title\'));if(/воспроиз|play|pause|пауза/i.test(a)){let p=e;for(let i=0;i<6&&p;i++,p=p.parentElement){let t=txt(p);if(t.length>5&&t.length<700){rows.add(p);break;}}}}" +\n                "for(const e of document.querySelectorAll(\'span,div\')){let d=clean(e.textContent);if(/^\\\\d{1,2}:\\\\d{2}$/.test(d)){let p=e;for(let i=0;i<6&&p;i++,p=p.parentElement){let t=txt(p);let n=t.split(/\\\\n+/).filter(Boolean).length;if(t.length>5&&t.length<700&&n>=2&&n<=12){rows.add(p);break;}}}}" +\n                "S.candidates=rows.size;" +\n                "for(const r of rows){try{" +\n                "let titleEl=r.querySelector(\'.audio_row__title_inner,.audio_row__title,[data-testid*=\\\\\\\"title\\\\\\\"],[data-test-id*=\\\\\\\"title\\\\\\\"],[class*=\\\\\\\"TrackTitle\\\\\\\"],[class*=\\\\\\\"trackTitle\\\\\\\"],[class*=\\\\\\\"AudioTitle\\\\\\\"],[class*=\\\\\\\"audioTitle\\\\\\\"]\');" +\n                "let artistEl=r.querySelector(\'.audio_row__performers,[data-testid*=\\\\\\\"artist\\\\\\\"],[data-test-id*=\\\\\\\"artist\\\\\\\"],[class*=\\\\\\\"performer\\\\\\\"],[class*=\\\\\\\"Artist\\\\\\\"],[class*=\\\\\\\"artist\\\\\\\"],[class*=\\\\\\\"Subtitle\\\\\\\"],[class*=\\\\\\\"subtitle\\\\\\\"]\');" +\n                "let title=txt(titleEl),artist=txt(artistEl);" +\n                "if(!artist){for(const a of r.querySelectorAll(\'a\')){let h=a.getAttribute(\'href\')||\'\';let z=txt(a);if(z&&!bad(z)&&(/artist/i.test(h)||/artist/i.test(a.className||\'\'))){artist=z;break;}}}" +\n                "if(artist&&title)add(artist,title,\'selector\');" +\n                "for(const e of r.querySelectorAll(\'[aria-label],[title]\')){let z=clean(e.getAttribute(\'aria-label\')||e.getAttribute(\'title\'));z=z.replace(/^(воспроизвести|play|pause|пауза)\\\\s*/i,\'\');let m=z.match(/^(.{1,180}?)\\\\s+[—–-]\\\\s+(.{1,220})$/);if(m)add(m[1],m[2],\'aria\');}" +\n                "let raw=(r.innerText||r.textContent||\'\').replace(/\\\\u00a0/g,\' \');let lines=raw.split(/\\\\n+/).map(clean).filter(x=>!bad(x));" +\n                "let uniq=[];for(const x of lines){if(!uniq.some(y=>y.toLowerCase()===x.toLowerCase()))uniq.push(x);}" +\n                "for(const x of uniq){let m=x.match(/^(.{1,180}?)\\\\s+[—–]\\\\s+(.{1,220})$/);if(m)add(m[1],m[2],\'line-split\');}" +\n                "if(artist&&!title){let q=uniq.find(x=>x.toLowerCase()!==artist.toLowerCase());if(q)add(artist,q,\'artist+line\');}" +\n                "if(title&&!artist){let q=uniq.find(x=>x.toLowerCase()!==title.toLowerCase());if(q)add(q,title,\'title+line\');}" +\n                "if(!artist&&!title&&uniq.length>=2)add(uniq[1],uniq[0],\'fallback\');" +\n                "}catch(x){}}" +\n                (doScroll ?\n                "let moved=false;const list=[document.scrollingElement,document.documentElement,document.body,...document.querySelectorAll(\'*\')];" +\n                "const sc=list.filter((e,i,a)=>e&&a.indexOf(e)===i&&e.scrollHeight>e.clientHeight+140&&e.clientHeight>120).sort((a,b)=>(b.scrollHeight-b.clientHeight)-(a.scrollHeight-a.clientHeight)).slice(0,8);" +\n                "for(const e of sc){try{let before=e.scrollTop;let jump=Math.max(420,Math.floor(e.clientHeight*0.82));e.scrollTop=Math.min(e.scrollHeight-e.clientHeight,before+jump);if(e.scrollTop>before+2)moved=true;}catch(x){}}" +\n                "let by=window.scrollY;window.scrollBy(0,Math.max(420,Math.floor(window.innerHeight*0.82)));if(window.scrollY>by+2)moved=true;" :\n                "let moved=false;") +\n                "return JSON.stringify({count:Object.keys(S.tracks).length,candidates:S.candidates,moved:moved,round:S.round,title:document.title||\'\',url:location.href});" +\n                "})()";\n    }\n\n    private void extractVkTracks() {\n        String js = "(function(){" +\n                "if(!window.__vk2s)return JSON.stringify({tracks:[],debug:{reason:\'state-missing\'}});" +\n                "return JSON.stringify({tracks:Object.values(window.__vk2s.tracks||{}),debug:{candidates:window.__vk2s.candidates||0,round:window.__vk2s.round||0,title:document.title||\'\',url:location.href}});" +\n                "})()";\n\n        vkWebView.evaluateJavascript(vkSnapshotScript(false), ignored -> vkWebView.evaluateJavascript(js, value -> {\n            try {\n                Object decoded = new JSONTokener(value).nextValue();\n                String json = decoded instanceof String ? (String) decoded : "{}";\n                JSONObject root = new JSONObject(json);\n                JSONArray arr = root.optJSONArray("tracks");\n                if (arr == null) arr = new JSONArray();\n                JSONObject debug = root.optJSONObject("debug");\n\n                vkTracks.clear();\n                Set<String> seen = new HashSet<>();\n                for (int i = 0; i < arr.length(); i++) {\n                    JSONObject o = arr.getJSONObject(i);\n                    String artist = o.optString("artist", "").trim();\n                    String title = o.optString("title", "").trim();\n                    String key = normalize(artist) + "|" + normalize(title);\n                    if (!artist.isEmpty() && !title.isEmpty() && seen.add(key)) {\n                        vkTracks.add(new Track(artist, title));\n                    }\n                }\n                updateTrackCount();\n                updateReadiness();\n                if (vkTracks.isEmpty()) {\n                    int candidates = debug == null ? 0 : debug.optInt("candidates", 0);\n                    String page = debug == null ? "" : debug.optString("title", "");\n                    vkStatusText.setText("Не нашёл треки в текущей странице VK" +\n                            (candidates > 0 ? " • кандидатов: " + candidates : "") +\n                            (page.isEmpty() ? "" : " • " + page));\n                    toast("Попробуй открыть именно раздел «Моя музыка» и нажать «Собрать» ещё раз");\n                } else {\n                    vkStatusText.setText("Готово — собрано " + vkTracks.size() + " трек" + pluralTracks(vkTracks.size()));\n                    hideVkOverlay();\n                    toast("Собрано треков: " + vkTracks.size());\n                }\n            } catch (Exception e) {\n                vkStatusText.setText("Не удалось разобрать страницу VK: " + e.getClass().getSimpleName());\n                toast("Оставил VK открытым — можно попробовать «Собрать» ещё раз");\n            }\n        }));\n    }\n\n    private String pluralTracks(int n) {\n        int x = Math.abs(n) % 100;\n        int y = x % 10;\n        if (x >= 11 && x <= 19) return "ов";\n        if (y == 1) return "";\n        if (y >= 2 && y <= 4) return "а";\n        return "ов";\n    }\n\n'
s = s[:start] + new_methods + s[end:]
p.write_text(s, encoding="utf-8")

bp = root / "app/build.gradle"
b = bp.read_text(encoding="utf-8")
b = b.replace("versionCode 2", "versionCode 3").replace("versionName '0.2.0'", "versionName '0.3.0'")
bp.write_text(b, encoding="utf-8")
print("Patched VK2SpotifyAndroid to v0.3.0")
